export interface ProfileSource { readonly image: string; readonly biography: readonly string[]; }
export interface BiographyLine { readonly key: string; readonly text: string; }
export interface ProfileView { readonly image: string; readonly lines: readonly BiographyLine[]; }

export function buildProfileView(source: ProfileSource): ProfileView {
  const image = source.image.trim();
  if (!image) throw new TypeError("image required");
  const counts = new Map<string, number>();
  const lines = source.biography.map(raw => {
    const text = raw.trim();
    if (!text) throw new TypeError("blank biography line");
    const count = (counts.get(text) ?? 0) + 1;
    counts.set(text, count);
    return { key: text, text };
  });
  return { image, lines };
}

