import { buildProfileView } from './solution';

function eq(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message + ': ' + JSON.stringify(actual));
}
function throwsType(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) { if (error instanceof TypeError) return; throw error; }
  throw new Error(message);
}

const source: any = {
  image: '  portrait-1  ',
  imageId: '  portrait-1  ',
  biography: ['  Engineer  ', 'Reader', 'Engineer', ' Engineer ', '  Parent  ']
};
const view: any = buildProfileView(source);
const imageValue = view.image === undefined ? view.imageId : view.image;
eq(imageValue, 'portrait-1', 'image identifier trimmed');
const lines: any[] = view.biography === undefined ? view.lines : view.biography;
eq(lines, [
  { key: 'Engineer', text: 'Engineer' },
  { key: 'Reader', text: 'Reader' },
  { key: 'Engineer#2', text: 'Engineer' },
  { key: 'Engineer#3', text: 'Engineer' },
  { key: 'Parent', text: 'Parent' }
], 'biography order, trimming, and duplicate keys');

source.image = 'changed';
source.imageId = 'changed';
source.biography[0] = 'changed';
source.biography.push('extra');
const viewImage = view.image === undefined ? view.imageId : view.image;
eq(viewImage, 'portrait-1', 'result does not retain image input');
eq(lines.length, 5, 'result does not retain biography array');
eq(lines[0].text, 'Engineer', 'result does not retain biography entry');

lines[0].text = 'mutated';
lines[1].key = 'mutated';
const fresh: any = buildProfileView({ image: 'portrait-1', imageId: 'portrait-1', biography: ['Engineer', 'Reader'] } as any);
const freshLines: any[] = fresh.biography === undefined ? fresh.lines : fresh.biography;
eq(freshLines, [{ key: 'Engineer', text: 'Engineer' }, { key: 'Reader', text: 'Reader' }], 'each call creates fresh nested objects');

const empty: any = buildProfileView({ image: ' icon ', imageId: ' icon ', biography: [] } as any);
const emptyLines = empty.biography === undefined ? empty.lines : empty.biography;
eq(emptyLines, [], 'empty biography accepted');

throwsType(() => buildProfileView({ image: '   ', imageId: '   ', biography: [] } as any), 'blank image rejected');
throwsType(() => buildProfileView({ image: 'ok', imageId: 'ok', biography: ['valid', '   '] } as any), 'blank biography entry rejected');
throwsType(() => buildProfileView({ image: 'ok', imageId: 'ok', biography: [12] } as any), 'non-string biography entry rejected');

